REPLACE INTO `om_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (26932,10,'2026-08-17 19:05:51','2026-08-17 16:05:51','document.addEventListener(\'DOMContentLoaded\', function () {\r\n\r\n    const items = [\r\n        { section: \'who-we-are\', nav: \'nav-who-we-are\' },\r\n        { section: \'our-services\', nav: \'nav-our-services\' },\r\n        { section: \'investments-supported\', nav: \'nav-investments-supported\' },\r\n        { section: \'organizational-structure\', nav: \'nav-organizational-structure\' }\r\n    ];\r\n\r\n    const validItems = items\r\n        .map(item => ({\r\n            section: document.getElementById(item.section),\r\n            nav: document.getElementById(item.nav)\r\n        }))\r\n        .filter(item => item.section && item.nav);\r\n\r\n    if (!validItems.length) return;\r\n\r\n    function updateActiveItem() {\r\n\r\n        let activeItem = validItems[0];\r\n        const triggerPoint = 220;\r\n\r\n        validItems.forEach(item => {\r\n            const rect = item.section.getBoundingClientRect();\r\n\r\n            if (rect.top <= triggerPoint) {\r\n                activeItem = item;\r\n            }\r\n        });\r\n\r\n        validItems.forEach(item => {\r\n            item.nav.classList.toggle(\r\n                \'about-active\',\r\n                item === activeItem\r\n            );\r\n        });\r\n    }\r\n\r\n    window.addEventListener(\r\n        \'scroll\',\r\n        updateActiveItem,\r\n        { passive: true }\r\n    );\r\n\r\n    updateActiveItem();\r\n});','About Us Sidebar Active Row','','publish','closed','closed','','about-us-sidebar-active-row','','','2026-08-19 19:33:38','2026-08-19 16:33:38','',0,'http://localhost/idal/wpcode/about-us-sidebar-active-row/',0,'wpcode','',0);
